// Compose two DISTINCT oriented square lifts at ONE shared root. Retain all four rows of one square and any subset of the other's four rows, in either cyclic direction. Check blue cliques directly on the joint graph; hereditary failure prunes supersets. Graph6 (n<63).
use std::io::{self,BufRead};
fn blue(a:&[u64],mut p:u64,t:u32)->bool{if t==0{return true}while p.count_ones()>=t{let i=p.trailing_zeros() as usize;p&=p-1;if blue(a,p&!a[i],t-1){return true}}false}
fn next(a:&mut Vec<u64>,s:u64,k:u32)->bool{let n=a.len();let p=((1u64<<n)-1)&!s;if blue(a,p,k){return false}for i in 0..n{a[i]|=((s>>i)&1)<<n}a.push(s);true}
fn pop(a:&mut Vec<u64>){a.pop();let f=(1u64<<a.len())-1;for x in a{*x&=f}}
fn ext(a:&mut Vec<u64>,r:&[u64;4],start:usize,k:u32,d:u32,best:&mut u32){*best=(*best).max(d);for i in start..4{if d+(4-i)as u32<=*best{break}if next(a,r[i],k){ext(a,r,i+1,k,d+1,best);pop(a)}}}
fn main(){let k:u32=std::env::args().nth(1).unwrap().parse().unwrap();for l in io::stdin().lock().lines(){let line=l.unwrap();let b=line.as_bytes();let n=(b[0]-63)as usize;let mut a=vec![0u64;n];let mut e=vec![];let mut h=0;for j in 0..n{for i in 0..j{if(b[1+h/6]-63)>>(5-h%6)&1!=0{a[i]|=1<<j;a[j]|=1<<i;e.push((i,j))}h+=1}}let balls:Vec<_>=e.iter().map(|&(i,j)|a[i]|a[j]).collect();let f=(1u64<<n)-1;let mut lifts=vec![];for j in 0..e.len(){for i in 0..j{if balls[i]&balls[j]!=0||blue(&a,f&!(balls[i]|balls[j]),k-3){continue}let (u,w)=e[i];let (v,x)=e[j];let c=[u,v,w,x];let dirs:[[u64;4];2]=std::array::from_fn(|dir|std::array::from_fn(|p|{let i=(p+2+dir)%4;a[c[i]]|(1<<c[(p+1-dir)%4])|(1<<c[(p+dir)%4])}));lifts.push(dirs)}}let mut best=0;let mut cross=0;if lifts.len()>1{for(i,dirs)in lifts.iter().enumerate(){for rows in dirs{let mut g=a.clone();for &s in rows{assert!(next(&mut g,s,k))}for(j,other)in lifts.iter().enumerate(){if i!=j{for r in other{ext(&mut g,r,0,k,0,&mut best)}}}}}cross=lifts.len()*(lifts.len()-1)/2}println!("{} {} {}",lifts.len(),cross,best)}}
